{
 "summary": "The file formalizes Theorem 1.1: a compact, convex, full-dimensional set S in R^n (n>0) with barycenter 0 and interior lattice points exactly {0} has volume at most (n+1)^n/n!. It also formalizes the sharpness claim: the simplex (n+1)Δ_n − (1,…,1) has barycenter 0 and volume (n+1)^n/n!, and it gives a `CenteredBody` attaining the bound. The statements look faithful; the only caveats are junk-value behaviour of `barycenter` outside the hypotheses and the misleading name `normalizedVolume`, neither of which affects the targets.",
 "glossary": [
  {"decl": "Ehrhart.Space", "line": 10, "plain": "R^n as Fin n → ℝ with the product Lebesgue measure `volume`", "standard_concept": "Euclidean space R^n with Lebesgue measure", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.integerPoint", "line": 12, "plain": "Casts z ∈ Z^n to R^n coordinatewise", "standard_concept": "inclusion Z^n ⊂ R^n", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.standardSimplex", "line": 15, "plain": "Δ_n = {x : x_i ≥ 0, Σ x_i ≤ 1} = conv{0, e_1, …, e_n}", "standard_concept": "standard simplex Δ_n", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.simplexDilation", "line": 18, "plain": "x ↦ (n+1)x − (1,…,1)", "standard_concept": "dilation by n+1 followed by translation by −(1,…,1)", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.centeredSimplex", "line": 21, "plain": "(n+1)Δ_n − (1,…,1)", "standard_concept": "the centered simplex of the paper", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.normalizedVolume", "line": 24, "plain": "Lebesgue measure of K, converted via toReal", "standard_concept": "vol(K)", "matches_standard": "yes", "note": "The name suggests a normalization, but it is plain Lebesgue volume (not multiplied by n!). `toReal` would turn ∞ into 0, but the target statements assume compactness, so the volume is finite."},
  {"decl": "Ehrhart.barycenter", "line": 27, "plain": "(1/vol K) ∫_K x dx", "standard_concept": "barycenter (centroid) of K", "matches_standard": "yes", "note": "Matches the standard notion when K has positive finite volume and is integrable. Otherwise it gives 0 via junk values (⁻¹ of 0, non-integrable integral = 0). Every target statement has compactness and nonempty interior, so this does not arise."},
  {"decl": "Ehrhart.interiorLatticePoints", "line": 30, "plain": "{z ∈ Z^n : z ∈ int K}", "standard_concept": "int(K) ∩ Z^n", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.CenteredBody", "line": 33, "plain": "Compact convex set with nonempty interior, barycenter 0, and interior lattice points exactly {0}", "standard_concept": "the convex bodies in Theorem 1.1", "matches_standard": "yes", "note": ""},
  {"decl": "Ehrhart.sharpConstant", "line": 41, "plain": "(n+1)^n / n!", "standard_concept": "(n+1)^n/n!", "matches_standard": "yes", "note": "The division is real division by n!, which is nonzero, so there is no junk."}
 ],
 "lean_claims": [
  {"theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "line": 48, "plain": "For every n, the barycenter of (n+1)Δ_n − (1,…,1) is 0."},
  {"theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "line": 52, "plain": "For n>0, vol((n+1)Δ_n − (1,…,1)) = (n+1)^n/n!."},
  {"theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "line": 56, "plain": "For n>0 there is a compact convex full-dimensional body with barycenter 0 and int ∩ Z^n = {0} whose volume is (n+1)^n/n!."},
  {"theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "line": 65, "plain": "For n>0 and S ⊂ R^n convex, compact, with nonempty interior, barycenter 0 and int(S) ∩ Z^n = {0}: vol(S) ≤ (n+1)^n/n!."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "A full-dimensional compact convex body K ⊂ R^n with barycenter 0 and int(K) ∩ Z^n = {0} satisfies vol(K) ≤ (n+1)^n/n!."},
  {"ref": "Sharpness remark (after Thm 1.1)", "plain": "The simplex (n+1)Δ_n − (1,…,1) has barycenter 0, no other interior lattice point, and volume (n+1)^n/n!."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1", "lean_theorem": "Ehrhart.Volume.ehrhart_volume_inequality_for_sets", "relation": "equivalent", "why": "Same hypotheses (convex, compact, nonempty interior, barycenter 0, interior lattice points = {0}) and same bound. The n>0 restriction is the natural reading and n=0 is not discussed in the excerpt."},
  {"paper_ref": "Sharpness remark", "lean_theorem": "Ehrhart.SimplexVolume.exists_centeredBody_sharp", "relation": "equivalent", "why": "Existence of an extremizer; the barycenter and volume of the specific simplex are given by the other two theorems."},
  {"paper_ref": "Sharpness remark (barycenter 0)", "lean_theorem": "Ehrhart.SimplexVolume.barycenter_centeredSimplex", "relation": "equivalent", "why": "Barycenter of the centered simplex is 0."},
  {"paper_ref": "Sharpness remark (volume)", "lean_theorem": "Ehrhart.SimplexVolume.normalizedVolume_centeredSimplex", "relation": "equivalent", "why": "Volume is (n+1)^n/n!."}
 ],
